parameters.jsCode:
const leadsBanco = $items('Busca os leads do banco');

const normLinkedin = (url) =>
  url ? url.trim().toLowerCase().replace(/\/$/, '') : '';

const linkedinExistentes = new Set(
  leadsBanco
    .map(item => normLinkedin(item.json.linkedin_url))
    .filter(Boolean)
);

const results = $items('Prospecting Contacts')[0].json.results || [];

const seen = new Set();

return results
  .map(lead => {
    const linkedin = normLinkedin(lead.socialLinks?.linkedin);
    if (!linkedin) return null;
    if (linkedinExistentes.has(linkedin)) return null;
    if (seen.has(linkedin)) return null; // dedup dentro do próprio batch
    seen.add(linkedin);

    const nome = [lead.firstName, lead.lastName]
      .filter(Boolean)
      .join(' ')
      .trim();
    if (!nome) return null;

    return {
      json: {
        nome,
        cargo: lead.jobTitle?.title ?? null,
        linkedin_url: lead.socialLinks?.linkedin ?? null,
        empresa_nome: lead.company?.name ?? null,
        empresa_site: lead.company?.domain ?? null,
        empresa_setor: lead.jobTitle?.departments?.[0] ?? null,
        origem: 'lusha_n8n',
        lusha_contact_id: lead.id ?? null,
        id_company_lusha: lead.company.id ?? null
      },
    };
  })
  .filter(Boolean);

fieldValues.fieldValue:
={{ (() => {
  const cfg  = $('Busca a config ativa do lusha').first().json;
  const pag  = $('Prospecting Contacts').first().json.pagination || {};
  const size = Math.min(Number(cfg.page_size) || 50, 50);
  const next = (Number(cfg.page) || 0) + 1;
  const total = Number(pag.total) || 0;
  // Se a proxima pagina passou do total, volta pro inicio em vez de
  // pedir offset inexistente (e queimar credito de api_search a seco).
  return (total > 0 && next * size >= total) ? 0 : next;
})() }}

parameters.jsonBody:
={{ (() => {
  const c   = $json;
  const arr = (v) => (Array.isArray(v) && v.length ? v : undefined);

  // A Lusha só devolve no máximo 50 contatos por página, mesmo que o
  // campo aceite até 100 no formulário. Por isso travamos em 50 aqui:
  // se mandar mais que isso, a busca dá erro.
  const size = Math.min(Number(c.page_size) || 50, 50);
  const page = Number(c.page) || 0;

  const companies = {
    sizes:    arr(c.company_sizes),
    revenues: arr(c.company_revenues)
  };

  // A Lusha trocou como identifica os setores das empresas: antes era
  // por número (ID), agora é pelo nome do setor (texto). Se a config
  // já tiver os nomes preenchidos, usa eles. Se não, usa os números
  // antigos como reserva, até a config ser atualizada.
  const labels = arr(c.company_industries_labels);
  if (labels) {
    companies.industriesLabels = labels;
  } else {
    companies.mainIndustriesIds = arr(c.company_industries);
    companies.subIndustriesIds  = arr(c.company_sub_industries);
  }

  const contacts = {
    departments:  arr(c.departments),
    seniorityIds: arr(c.seniorities),
    jobTitles:    arr(c.job_titles),
    locations:    [{ country: "Brazil" }]
  };

  // Se a config tiver "existing_data_points" preenchido (ex: ["phone"]),
  // a busca só traz contato que já tem telefone ou email cadastrado.
  // Se deixar vazio, traz todo mundo, com ou sem contato.
  const edp = arr(c.existing_data_points);
  if (edp) {
    contacts.existingDataPoints          = edp;
    contacts.existingDataPointsCondition = "or";
  }

  const body = {
    pagination: { page, size },
    filters: {
      contacts:  { include: contacts  },
      companies: { include: companies }
    },
    // Limite fixo de 2 contatos por empresa. Se a empresa tiver mais
    // gente que bate no filtro, só os 2 primeiros vêm — o resto fica
    // de fora dessa busca.
    options: { maxContactsPerCompany: 2 }
  };

  return JSON.stringify(body);
})() }}

